import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>تحتاج صورة كنص: شعار لورقة أنماط أو أيقونة لبريد أو صورة لـJSON. التحويل يستغرق نحو دقيقة بمجرد أن تعرف الخطوات.</p>\n<p>هذا الدليل يأخذك خطوة بخطوة لتحويل صورة إلى Base64 في أربع خطوات: رفع الملف واختيار صيغة الإخراج ونسخ السلسلة أو تنزيلها ولصقها في كودك.</p>\n<p>لا برنامج للتثبيت ولا حساب للإنشاء ولا شيء يُرفع إلى أي مكان: تُرمّز الصورة محليًا في متصفحك من البداية إلى النهاية.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج ملف الصورة بصيغة PNG أو JPG أو WebP أو GIF أو SVG أو BMP أو ICO، حتى 15 MB: الشعارات والأيقونات والصور الصغيرة هي المرشحون المعتادون.</p>\n<p>اعرف إلى أين تذهب السلسلة: صفحة HTML تريد URL بيانات، وورقة أنماط تريد قيمة CSS url()، وAPI غالبًا تريد السلسلة الخام دون أي بادئة. وإذا كانت الصورة كبيرة، فكر في تصغيرها أولًا: صورة 2 MB تصبح سلسلة 2.7 MB، يصعب نسخها وبطيئة المعالجة، بينما نسخة مضغوطة قد تكون أصغر بكثير.</p>\n<p>والمتصفح هو كل البرامج التي تحتاجها: تعمل الأداة في Chrome وSafari وFirefox وEdge، على الحاسوب والهاتف، دون أي إضافة.</p>\n<h2 id=\"step-1-upload-or-paste\">الخطوة 1: ارفع الصورة أو الصق لقطة شاشة</h2>\n<p>افتح <a href=\"/ar/tahwil-as-sura-ila-base64/\">محوّل الصورة إلى Base64</a> واسحب صورتك إلى منطقة الرفع. ويمكنك أيضًا النقر على المنطقة لاختيار ملف من جهازك.</p>\n<p>وإذا كانت الصورة على شاشتك الآن، انسخها والصقها بـCtrl+V: تقبل الأداة صور الحافظة مباشرة، فتُرمّز لقطة دون حفظ ملف. وتقرأ الأداة الملف وتُظهر معاينة بأبعادها وصيغتها: تحقق من أن المعاينة هي الصورة التي أردتها، لأن السلسلة التي تنسخها ستكون تلك الصورة بالضبط.</p>\n<p>وإذا رفعت الملف الخطأ، رمّز آخر من الأداة: يُستبدل الإخراج السابق، وتستطيع متابعة العمل دون إعادة تحميل الصفحة.</p>\n<h2 id=\"step-2-choose-output-format\">الخطوة 2: اختر صيغة الإخراج</h2>\n<p>أربعة تبويبات فوق منطقة الإخراج: URL بيانات وخام وHTML وCSS. اختر ما يطابق أين تذهب السلسلة.</p>\n<p>اختر URL بيانات عندما تحتاج URI كاملة لمصدر صورة أو خلفية ورقة أنماط: تشمل نوع الوسائط ووسم الترميز، فتعمل في أي مكان. واختر خام عندما ترسل الصورة إلى API أو تحفظها في قاعدة بيانات: الإخراج الخام هو السلسلة فقط، دون بادئة، وهي الصيغة التي تتوقعها معظم API.</p>\n<p>اختر HTML عندما تريد عنصر صورة جاهزًا: تولّد الأداة الوسم مع URL البيانات كمصدر وتملأ سمتي العرض والارتفاع تلقائيًا. واختر CSS عندما تريد قيمة خلفية جاهزة لورقة أنماط.</p>\n<h2 id=\"step-3-copy-or-download\">الخطوة 3: انسخ الإخراج أو نزّله</h2>\n<p>انقر زر نسخ الإخراج لوضع السلسلة في حافظتك: للسلاسل القصيرة مثل الأيقونات والشعارات، هذا كل ما تحتاجه.</p>\n<p>وللسلاسل الطويلة، استخدم زر التنزيل: نسخ سلسلة عدة ميغابايت قد يكون بطيئًا أو غير موثوق، بينما ملف نصي منزّل يحمل الإخراج الدقيق دون قطع. وإذا حظر متصفحك الوصول إلى الحافظة، ستخبرك الأداة: اسمح بإذن الحافظة للصفحة، أو استخدم زر التنزيل كبديل لا يحتاج أي إذن.</p>\n<p>راجع نسبة الزيادة المعروضة بجانب الإخراج: تخبرك كم أكبر السلسلة من الملف الأصلي، غالبًا نحو 33 بالمئة إضافة إلى قليل للتغليف.</p>\n<h2 id=\"step-4-paste-into-code\">الخطوة 4: الصق السلسلة في كودك</h2>\n<p>الصق الإخراج حيث ينتمي: URL البيانات في مصدر صورة أو ورقة أنماط، والسلسلة الخام في حقل JSON، ومقتطف HTML في صفحة، وقيمة CSS في خاصية.</p>\n<p>اختبر النتيجة فورًا: افتح الصفحة أو أرسل بريد الاختبار أو استدعِ API، وتأكد من ظهور الصورة. سلسلة ملصوقة في الحقل الخطأ ستفشل بصمت أو تُظهر صورة مكسورة. واحتفظ بملف الصورة الأصلي: إذا احتاجت النسخة المضمنة تغييرًا أبدًا، ستعيد الترميز من الأصل بدل فك السلسلة وإعادة ترميزها.</p>\n<p>ولشعار أو أيقونة، فكر في حفظ المقتطف في مشروعك كمتغير أو جزئي قابل لإعادة الاستخدام: هكذا تعيش السلسلة الطويلة في مكان واحد بدل لصقها في كل ملف يحتاجها.</p>\n<h2 id=\"encoding-an-svg-logo\">كيف ترمّز شعار SVG</h2>\n<p>شعارات SVG تُرمّز دون مشكلة لأنها نص أصلًا: ارفع ملف SVG وتنتج الأداة سلسلة Base64 تُفك عودة إلى نفس الرسم المتجه.</p>\n<p>تبدأ URL بيانات SVG بـdata:image/svg+xml;base64، متبوعة بالسلسلة: الصقها في مصدر صورة فيُعرض الشعار حادًا بأي حجم. وانتبه للحجم مع ذلك: SVG معقد بكثير من المسارات قد يكون كبيرًا، وصيغته Base64 أكبر بثلث إضافي. شعار بسيط جيد؛ رسم مفصل قد يكون أفضل كملف مرتبط.</p>\n<p>ولـSVG صغيرة جدًا، فكر في SVG بسيط مرمز لـURL بدل Base64: إنه أقصر، لكنه يحتاج هروبًا دقيقًا، فـBase64 يبقى الخيار الأكثر أمانًا افتراضيًا.</p>\n<h2 id=\"encoding-a-favicon\">كيف ترمّز favicon</h2>\n<p>ملفات ICO لـfavicon تعمل في المحوّل مثل أي صيغة أخرى: ارفع ملف .ico وانسخ URL البيانات لاستخدامها في صفحة ملف واحد أو قالب بريد.</p>\n<p>معظم المواقع يجب أن تربط favicon كملف بدل تضمينه: favicon مرتبط يخزنه المتصفح مؤقتًا، بينما مضمن يُنزّل مع كل صفحة. والتضمين منطقي لصفحات الملف الواحد والمستندات دون اتصال وقوالب البريد، حيث لا يمكن جلب أي ملف منفصل: في تلك السياقات، يظهر الأيقونة المضمنة فورًا.</p>\n<p>وإذا لم يكن لديك favicon بعد، يستطيع <a href=\"/ar/munshi-favicon/\">مولد favicon</a> إنشاء واحد من أي صورة، ثم تستطيع ترميز النتيجة هنا.</p>\n<h2 id=\"encoding-for-html-email\">كيف ترمّز صورًا لبريد HTML</h2>\n<p>بريد HTML لا يستطيع الاعتماد على ملفات صور خارجية، لأن كثيرًا من العملاء يحظر الصور البعيدة افتراضيًا: تضمين الصورة كـURL بيانات يجعلها تظهر فورًا.</p>\n<p>أبقِ صور البريد المضمنة صغيرة: شعار أو لافتة صغيرة يعملان جيدًا، لكن صورة فوتوغرافية كبيرة تجعل الرسالة ثقيلة وبطيئة الفتح على الهاتف. واختبر قبل الإرسال: بعض عملاء البريد يحظر صور Base64 المضمنة، وقد تصل رسالتك بصور مكسورة لهؤلاء القراء. أرسل اختبارًا إلى العملاء الذين يستخدمهم جمهورك.</p>\n<p>وعندما يحظر عميل Base64، عُد إلى صورة مستضافة بـURL عادي: الصورة المستضافة تحتاج أن يحمّل القارئ محتوى بعيدًا، لكنها تعمل في كل عميل يسمح بذلك.</p>\n<h2 id=\"encoding-for-api-json\">كيف ترمّز صورًا لرفع JSON في API</h2>\n<p>لا يستطيع JSON حمل بيانات ثنائية، فنقاط رفع الصور التي تقبل JSON تتوقع الصورة كسلسلة Base64: يعطيك تبويب الإخراج الخام تلك الصيغة بالضبط.</p>\n<p>انسخ السلسلة الخام إلى حقل JSON الذي توثقه API، وأرسل نوع الوسائط في حقل منفصل إن طلبته API: يفك الخادم السلسلة ويعيد بناء الملف. وانتبه لحجم الرفع: صورة 1 MB تصبح حقل JSON 1.4 MB، وبعض API ترفض رفعًا فوق حد: اضغط الصورة قبل الترميز إن كان لـAPI حد.</p>\n<p>اختبر أولًا بصورة صغيرة: رحلة ذهاب وإياب ناجحة مع أيقونة صغيرة تثبت أن أسماء الحقول والصيغة صحيحة قبل إرسال صورة إنتاج كبيرة.</p>\n<h2 id=\"shrinking-before-encoding\">كيف تصغّر صورة قبل الترميز</h2>\n<p>ترميز صورة كبيرة ينتج سلسلة طويلة جدًا، والسلاسل الطويلة مزعجة للنسخ وبطيئة المعالجة وثقيلة الحفظ: التصغير أولًا يستحق العناء دائمًا تقريبًا.</p>\n<p>اضغط الصورة بـ<a href=\"/ar/\">ضاغط الصور</a> قبل ترميزها: صورة مخففة من 2 MB إلى 200 KB تنتج سلسلة أقصر عشر مرات، بفقدان جودة غالبًا غير مرئي. وغيّر الحجم أيضًا عندما يكون حجم العرض صغيرًا: أيقونة معروضة عند 64 بكسلًا لا تحتاج مصدر 2000 بكسل، والمصدر الأصغر يُرمّز إلى سلسلة أقصر بكثير.</p>\n<p>وللصور الفوتوغرافية، حوّل إلى JPG قبل الترميز إذا لم تحتج شفافية: ملفات JPG أصغر بكثير من PNG للصور الفوتوغرافية، والملف الأصغر يعني سلسلة أقصر.</p>\n<h2 id=\"troubleshooting-clipboard\">حل المشاكل: مشاكل النسخ إلى الحافظة</h2>\n<p>إذا لم يفعل زر النسخ شيئًا، فقد يكون متصفحك حظر الوصول إلى الحافظة: ستعرض الأداة رسالة تشرح الحظر، ويمكنك السماح بالإذن للصفحة.</p>\n<p>بعض المتصفحات تسمح بالكتابة إلى الحافظة فقط بعد إيماءة مستخدم على صفحة آمنة: النقر على الزر يُحسب إيماءة، لكن متصفحًا قديمًا أو ضبطًا صارمًا قد يحظرها مع ذلك. وزر التنزيل هو البديل الموثوق: يحفظ الإخراج الدقيق كملف نصي دون استخدام الحافظة، ويمكنك فتح الملف والنسخ منه.</p>\n<p>وعلى الهاتف، السلاسل الطويلة قد تكون بطيئة النسخ: نزّل ملف الإخراج وشاركه مع التطبيق الذي تحتاجه، بدل محاربة الحافظة.</p>\n<h2 id=\"troubleshooting-large-strings\">حل المشاكل: سلاسل طويلة جدًا</h2>\n<p>سلسلة طويلة طبيعية لصورة كبيرة، لكنها قد تجعل محررك بطيئًا: لصق سلسلة 2 MB في ملف كود قد يجمّد محررًا خفيفًا لثوانٍ.</p>\n<p>قسّم العمل: احفظ السلسلة في ملف منفصل أو متغير، وأشِر إليها من الكود الذي يحتاجها. هذا يبقي ملفاتك الرئيسية مقروءة ومحررك رشيقًا. وإذا كسرت السلسلة بناءك، راجع حدود طول السطر: بعض الأدوات تلف أو تقص الأسطر الطويلة جدًا، ما يفسد السلسلة. ملف منزّل يتجنب ذلك التلف.</p>\n<p>وعندما تبدو سلسلة طويلة جدًا للتعامل معها، أعد النظر في التضمين: ملف صورة مرتبط غالبًا هو الخيار الأفضل لأي شيء أكبر من بضع مئات الكيلوبايت.</p>\n<h2 id=\"encoding-another-image\">كيف ترمّز صورة أخرى بعد الأولى</h2>\n<p>لترميز صورة ثانية، ارفعها من الأداة دون إعادة تحميل الصفحة: الصورة الجديدة تستبدل القديمة، ويتحدث الإخراج إلى السلسلة الجديدة.</p>\n<p>انسخ الإخراج أولًا قبل التبديل، لأن استبدال الصورة يمسح السلسلة السابقة: ملف منزّل هو السجل الأكثر أمانًا إن احتجت السلسلتين. والعمل مع مجموعة أيقونات سريع هكذا: ارفع وانسخ وارفع التالي وانسخ مجددًا، ومجموعة الأيقونات كلها تُرمّز في دقائق.</p>\n<p>أبقِ الملفات الأصلية منظمة وأنت تعمل: مجلد صور مصدر ومجلد مقابل لملفات نص الإخراج يمنعان الالتباس الذي يحدث عندما تختلط كل الملفات.</p>\n<h2 id=\"encoding-for-social-and-messaging\">كيف ترمّز صورًا للتواصل الاجتماعي والمراسلة</h2>\n<p>منشورات التواصل الاجتماعي ورسائل المحادثة تقبل أحيانًا صورًا كنص فقط، خصوصًا في الروبوتات وwebhooks وسير العمل الآلي: سلسلة Base64 تتيح لصورة أن تسافر داخل رسالة.</p>\n<p>أبقِ هذه الصور صغيرة جدًا: API محادثة قد تحد حجم الرسالة لبضع عشرات الكيلوبايت، وصورة فوتوغرافية مرمزة بـBase64 ستتجاوز ذلك الحد قبل وصولها. ولروبوتات المحادثة، أيقونة صغيرة أو مصغرة أقل من 10 KB تُرمّز إلى سلسلة تناسب رسالة براحة: أي شيء أكبر يجب رفعه كملف والإشارة إليه.</p>\n<p>بعض أدوات الأتمتة تقبل URL بيانات حيث تحتاج خلافًا صورة مستضافة: هذا مفيد عندما تُولد الصورة في اللحظة ولا يوجد مكان لاستضافتها بعد. واختبر الرحلة الكاملة ذهابًا وإيابًا قبل أتمتتها: أرسل رسالة بالصورة المرمزة وتأكد من ظهورها عند المستلم، وبعدها فقط ابنِ السير حولها.</p>\n<p>وتذكر أن السلسلة مرئية لأي شخص يستطيع رؤية حمولة الرسالة: لا ترمّز صورًا خاصة في رسائل أو سجلات أو webhooks حيث قد يُحفظ النص أو يُعاد إرساله.</p>\n<h2 id=\"quick-reference-checklist\">قائمة مرجعية سريعة</h2>\n<p>ارفع الصورة واختر تبويب الإخراج لوجهتك، وانسخ السلسلة أو نزّلها: اختبرها في مكانها قبل نشر أي شيء يعتمد عليها.</p>\n<p>صغّر الصور الكبيرة قبل الترميز، واستخدم Base64 الخام لـAPI، وفضّل ملفًا مرتبطًا على سلسلة مضمنة لأي شيء كبير أو مشترك بين صفحات.</p>\n<p>للسياق الكامل، اقرأ <a href=\"/ar/blog/dalil-tahwil-as-sura-ila-base64/\">دليل تحويل الصورة إلى Base64 الكامل</a>، ولإطار القرار راجع <a href=\"/ar/blog/suwar-base64-mata-tudamman/\">صور Base64: متى تُضمّن ومتى لا</a>. ولفك سلسلة عودة إلى ملف، استخدم <a href=\"/ar/tahwil-base64-ila-sura/\">مفكك Base64 إلى صورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكنني تحويل صورة إلى Base64 على هاتفي؟","answer":"نعم، يعمل المحوّل في متصفحات الهاتف على iOS وAndroid: ارفع الصورة من معرضك واختر تبويب الإخراج وانسخ السلسلة. وللسلاسل الطويلة جدًا، نزّل ملف الإخراج بدل النسخ."},{"question":"لماذا يضيف تبويب HTML العرض والارتفاع إلى وسم الصورة؟","answer":"يحتاج المتصفح الأبعاد لحجز مساحة قبل فك الصورة. ودونها، يتحرك تخطيط الصفحة عندما تظهر الصورة، ما يضر تجربة القراءة ودرجة سرعة الصفحة."},{"question":"هل يجب أن أستخدم Base64 أم ملف صورة عادي لشعار موقعي؟","answer":"لشعار يظهر في صفحات كثيرة، ملف مرتبط عادي غالبًا أفضل لأن المتصفح يخزنه مؤقتًا مرة واحدة. ويفوز Base64 عندما يجب أن تكون الصفحة ملفًا واحدًا، أو عندما يكون الشعار صغيرًا ولا يستحق طلبًا منفصلًا."},{"question":"ما الفرق بين URL بيانات وBase64 الخام؟","answer":"URL بيانات هو URI الكامل ببادئة البيانات ونوع الوسائط ووسم الترميز، جاهز للاستخدام كمصدر صورة. وBase64 الخام هو السلسلة فقط، دون بادئة، وهي الصيغة التي تتوقعها معظم API وقواعد البيانات."},{"question":"هل التحويل إلى Base64 يزيل بيانات صورتي الوصفية؟","answer":"الترميز نفسه لا يزيل شيئًا، لأن السلسلة تحمل البايتات الأصلية الدقيقة. ومع ذلك، بعض السير يزيل البيانات الوصفية قبل الترميز لتكون السلسلة أقصر. وإذا همّت الخصوصية، أزل البيانات الوصفية قبل الترميز."},{"question":"هل يمكنني ترميز لقطة شاشة مباشرة دون حفظ ملف؟","answer":"نعم، انسخ لقطة الشاشة واضغط Ctrl+V في الأداة فتُرمّز فورًا. وهذه أسرع طريقة للحصول على URL بيانات للقطة شاشة أو عنصر واجهة أو مخطط."}];
